  get visibleProducts(){return this.productFilter==='All'?this.products:this.products.filter(p=>p.category.toLowerCase()===this.productFilter.toLowerCase())}
  cart:CartLine[]=[];cartOpen=false;selectedProduct:Product|null=null;selectedSize='';checkoutStep=0;paymentMethod='Demo';orderReceived=false;checkoutError='';
  delivery={name:'',email:'',phone:'',address:'',city:'',instructions:''};
  get cartCount(){return this.cart.reduce((n,l)=>n+l.qty,0)}get cartTotal(){return this.cart.reduce((n,l)=>n+l.qty*l.product.price,0)}
  openProduct(p:Product){this.selectedProduct=p;this.selectedSize=''}
  addToCart(p:Product){const line=this.cart.find(l=>l.product.name===p.name);if(line)line.qty++;else this.cart.push({product:p,qty:1});this.selectedProduct=null}
  changeQty(line:CartLine,delta:number){line.qty+=delta;if(line.qty<1)this.removeLine(line)}removeLine(line:CartLine){this.cart=this.cart.filter(l=>l!==line)}
  startCheckout(){this.cartOpen=false;this.checkoutStep=1;this.orderReceived=false}
