  async completeOrder(){
    this.checkoutError='';
    if(!this.yocoCheckoutEndpoint){this.checkoutError='No real checkout is configured in this preview. Use the official store or demo checkout.';return;}
    try{
      const response=await fetch(this.yocoCheckoutEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({currency:'ZAR',amountInCents:this.cartTotal*100,items:this.cart.map(line=>({name:line.product.name,quantity:line.qty,unitAmountInCents:line.product.price*100}))})});
      if(!response.ok)throw new Error('Checkout could not be created.');
      const result=await response.json() as {redirectUrl?:string};
      if(!result.redirectUrl||!/^https:\/\//.test(result.redirectUrl))throw new Error('The payment provider returned an invalid checkout link.');
      window.location.assign(result.redirectUrl);
    }catch(error){this.checkoutError=error instanceof Error?error.message:'Unable to start secure checkout.';}
  }
